if not ui.is_dir():
    raise SystemExit("Expected CalorieCounter project after unzip")
FILES = {'FoodPicker.kt': 'package com.example.caloriecounter.ui\n\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.rememberScrollState\nimport androidx.compose.foundation.verticalScroll\nimport androidx.compose.material3.*\nimport androidx.compose.runtime.*\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.unit.dp\nimport com.example.caloriecounter.AppViewModel\nimport com.example.caloriecounter.data.*\nimport com.google.gson.Gson\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.withContext\nimport kotlinx.coroutines.launch\nimport okhttp3.OkHttpClient\nimport okhttp3.Request\nimport java.net.URLEncoder\nimport java.util.concurrent.TimeUnit\n\ndata class SearchResponse(val products: List<SearchProduct>?)\ndata class SearchProduct(val code: String?, val product_name: String?, val brands: String?, val nutriments: OffNutriments?)\n\nprivate suspend fun searchFoods(query: String): List<ProductEntity> = withContext(Dispatchers.IO) {\n    val url = "https://world.openfoodfacts.org/cgi/search.pl?search_terms=" +\n        URLEncoder.encode(query, "UTF-8") +\n        "&search_simple=1&action=process&json=1&page_size=20&fields=code,product_name,brands,nutriments"\n    val client = OkHttpClient.Builder().callTimeout(45, TimeUnit.SECONDS).build()\n    client.newCall(Request.Builder().url(url)\n        .header("User-Agent", "CalorieCounter/1.1 (Android personal nutrition diary)").build()).execute().use { response ->\n        if (!response.isSuccessful) error("Search failed (${response.code})")\n        val body = response.body?.string() ?: error("Empty response")\n        Gson().fromJson(body, SearchResponse::class.java).products.orEmpty().mapNotNull { p ->\n            val n = p.nutriments ?: return@mapNotNull null\n            val energy = n.kcal ?: n.energyKj?.div(4.184) ?: return@mapNotNull null\n            ProductEntity(p.code ?: "", p.product_name?.takeIf { it.isNotBlank() } ?: return@mapNotNull null,\n                p.brands, null, energy, n.protein ?: 0.0, n.carbs ?: 0.0, n.sugars ?: 0.0,\n                n.fat ?: 0.0, n.saturatedFat ?: 0.0, n.fibre ?: 0.0, n.salt ?: 0.0)\n        }\n    }\n}\n\n@Composable\nfun FoodPicker(viewModel: AppViewModel, onPicked: (ProductEntity) -> Unit) {\n    var scanning by remember { mutableStateOf(false) }\n    var query by remember { mutableStateOf("") }\n    var results by remember { mutableStateOf<List<ProductEntity>>(emptyList()) }\n    var busy by remember { mutableStateOf(false) }\n    var message by remember { mutableStateOf("") }\n    val scope = rememberCoroutineScope()\n    if (scanning) {\n        Column(Modifier.fillMaxSize()) {\n            TextButton(onClick = { scanning = false }) { Text("Cancel scan") }\n            Box(Modifier.weight(1f)) {\n                ScanScreen { barcode ->\n                    scanning = false\n                    busy = true\n                    message = "Looking up barcode…"\n                    viewModel.fetchProduct(barcode) { product ->\n                        busy = false\n                        if (product == null) message = "Product unavailable. Try searching or manual entry."\n                        else { message = ""; onPicked(product) }\n                    }\n                }\n            }\n        }\n    } else {\n        Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp),\n            verticalArrangement = Arrangement.spacedBy(10.dp)) {\n            Text("Find food", style = MaterialTheme.typography.headlineSmall)\n            Button(onClick = { scanning = true }, enabled = !busy) { Text("Scan barcode") }\n            OutlinedTextField(query, { query = it }, label = { Text("Food or brand name") }, modifier = Modifier.fillMaxWidth())\n            Button(enabled = !busy && query.trim().length >= 2, onClick = {\n                scope.launch {\n                    busy = true\n                    message = "Searching…"\n                    try {\n                        results = searchFoods(query.trim())\n                        message = if (results.isEmpty()) "No results. Try a brand name or use manual entry." else "Choose a product. Check its label and nutrition basis."\n                    } catch (e: Exception) {\n                        message = "Search unavailable: ${e.message}. Try again later."\n                    } finally { busy = false }\n                }\n            }) { Text("Search") }\n            Text(message)\n            Text("Open Food Facts is mainly packaged foods. Fresh foods may require manual entry. Missing nutrient fields are treated as zero; check the label.", style = MaterialTheme.typography.bodySmall)\n            results.forEach { food ->\n                OutlinedButton(onClick = { onPicked(food) }, modifier = Modifier.fillMaxWidth()) {\n                    Column(Modifier.fillMaxWidth()) {\n                        Text(food.name)\n                        Text(food.brand.orEmpty())\n                        Text("%.0f kcal per 100 g/ml".format(food.kcalPer100))\n                    }\n                }\n            }\n        }\n    }\n}\n\n@Composable\nfun SearchDiaryScreen(viewModel: AppViewModel, onSaved: () -> Unit) {\n    var selected by remember { mutableStateOf<ProductEntity?>(null) }\n    var amount by remember { mutableStateOf("100") }\n    var meal by remember { mutableStateOf("Lunch") }\n    val food = selected\n    if (food == null) FoodPicker(viewModel) { selected = it }\n    else Column(Modifier.verticalScroll(rememberScrollState()).padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {\n        Text(food.name, style = MaterialTheme.typography.headlineSmall)\n        Text("Use grams for per-100g labels; ml for per-100ml labels. Do not interchange weight and volume.")\n        OutlinedTextField(amount, { amount = it }, label = { Text("Amount (g or ml to match label)") })\n        OutlinedTextField(meal, { meal = it }, label = { Text("Meal") })\n        val q = amount.toDoubleOrNull()?.takeIf { it.isFinite() && it > 0 }\n        Text("%.0f kcal".format(food.kcalPer100 * (q ?: 0.0) / 100))\n        Button(enabled = q != null, onClick = {\n            val factor = (q ?: return@Button) / 100\n            viewModel.addEntry(DiaryEntryEntity(date = java.time.LocalDate.now().toString(), mealType = meal.ifBlank { "Other" },\n                barcode = food.barcode, name = food.name, quantityGrams = q,\n                kcal = food.kcalPer100 * factor, protein = food.proteinPer100 * factor,\n                carbs = food.carbsPer100 * factor, fat = food.fatPer100 * factor))\n            onSaved()\n        }) { Text("Log food") }\n        TextButton(onClick = { selected = null }) { Text("Choose another food") }\n    }\n}\n', 'RecipeEditorScreen.kt': 'package com.example.caloriecounter.ui\n\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.rememberScrollState\nimport androidx.compose.foundation.verticalScroll\nimport androidx.compose.material3.*\nimport androidx.compose.runtime.*\nimport androidx.compose.runtime.saveable.rememberSaveable\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.unit.dp\nimport com.example.caloriecounter.AppViewModel\nimport com.example.caloriecounter.data.*\n\n@Composable\nfun RecipeEditorScreen(viewModel: AppViewModel, onSaved: () -> Unit) {\n    var name by rememberSaveable { mutableStateOf("") }\n    var servings by rememberSaveable { mutableStateOf("1") }\n    var picking by remember { mutableStateOf(false) }\n    var saving by remember { mutableStateOf(false) }\n    val ingredients = remember { mutableStateListOf<RecipeIngredientEntity>() }\n    val quantities = remember { mutableStateListOf<String>() }\n    var manualName by rememberSaveable { mutableStateOf("") }\n    var kcal by rememberSaveable { mutableStateOf("") }\n    var protein by rememberSaveable { mutableStateOf("") }\n    var carbs by rememberSaveable { mutableStateOf("") }\n    var fat by rememberSaveable { mutableStateOf("") }\n    if (picking) {\n        Column(Modifier.fillMaxSize()) {\n            TextButton(onClick = { picking = false }) { Text("Back to recipe") }\n            Box(Modifier.weight(1f)) {\n                FoodPicker(viewModel) { p ->\n                    ingredients.add(RecipeIngredientEntity(recipeId = 0, name = p.name,\n                        quantityGrams = 100.0, kcalPer100 = p.kcalPer100,\n                        proteinPer100 = p.proteinPer100, carbsPer100 = p.carbsPer100, fatPer100 = p.fatPer100))\n                    quantities.add("100")\n                    picking = false\n                }\n            }\n        }\n        return\n    }\n    Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp),\n        verticalArrangement = Arrangement.spacedBy(12.dp)) {\n        Text("New meal / recipe", style = MaterialTheme.typography.headlineSmall)\n        OutlinedTextField(name, { name = it }, label = { Text("Recipe name") }, modifier = Modifier.fillMaxWidth())\n        OutlinedTextField(servings, { servings = it }, label = { Text("Number of servings") })\n        Button(onClick = { picking = true }) { Text("Scan or search for ingredient") }\n        Text("Ingredients", style = MaterialTheme.typography.titleLarge)\n        Text("For each ingredient, use g for per-100g values or ml for per-100ml values. Quantities refer to the same prepared/drained state as the nutrition label.")\n        ingredients.forEachIndexed { index, ingredient ->\n            Card(Modifier.fillMaxWidth()) {\n                Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {\n                    Text(ingredient.name)\n                    OutlinedTextField(quantities[index], { quantities[index] = it }, label = { Text("Amount in recipe (g or ml)") })\n                    Text("%.0f kcal".format(ingredient.kcalPer100 * (quantities[index].toDoubleOrNull() ?: 0.0) / 100))\n                    TextButton(onClick = { ingredients.removeAt(index); quantities.removeAt(index) }) { Text("Remove") }\n                }\n            }\n        }\n        Text("Manual ingredient", style = MaterialTheme.typography.titleMedium)\n        OutlinedTextField(manualName, { manualName = it }, label = { Text("Ingredient name") })\n        OutlinedTextField(kcal, { kcal = it }, label = { Text("kcal per 100 g/ml") })\n        OutlinedTextField(protein, { protein = it }, label = { Text("Protein g per 100 g/ml") })\n        OutlinedTextField(carbs, { carbs = it }, label = { Text("Carbs g per 100 g/ml") })\n        OutlinedTextField(fat, { fat = it }, label = { Text("Fat g per 100 g/ml") })\n        val manualValid = manualName.isNotBlank() && kcal.toDoubleOrNull()?.let { it.isFinite() && it >= 0 } == true &&\n            listOf(protein, carbs, fat).all { it.isBlank() || it.toDoubleOrNull()?.let { n -> n.isFinite() && n >= 0 } == true }\n        OutlinedButton(enabled = manualValid, onClick = {\n            ingredients.add(RecipeIngredientEntity(recipeId = 0, name = manualName.trim(), quantityGrams = 100.0,\n                kcalPer100 = kcal.toDouble(), proteinPer100 = protein.toDoubleOrNull() ?: 0.0,\n                carbsPer100 = carbs.toDoubleOrNull() ?: 0.0, fatPer100 = fat.toDoubleOrNull() ?: 0.0))\n            quantities.add("100")\n            manualName = ""; kcal = ""; protein = ""; carbs = ""; fat = ""\n        }) { Text("Add manual ingredient") }\n        val count = servings.toIntOrNull() ?: 0\n        val validAmounts = quantities.all { it.toDoubleOrNull()?.let { n -> n.isFinite() && n > 0 } == true }\n        val total = ingredients.indices.sumOf { ingredients[it].kcalPer100 * (quantities[it].toDoubleOrNull() ?: 0.0) / 100 }\n        Text("Recipe total: %.0f kcal".format(total))\n        if (count > 0) Text("Per serving: %.0f kcal".format(total / count))\n        Button(enabled = !saving && name.isNotBlank() && count > 0 && ingredients.isNotEmpty() && validAmounts, onClick = {\n            saving = true\n            viewModel.saveRecipe(name.trim(), count, ingredients.mapIndexed { i, item -> item.copy(quantityGrams = quantities[i].toDouble()) }) { onSaved() }\n        }) { Text(if (saving) "Saving…" else "Save recipe") }\n    }\n}\n'}
